('House of Sunny', 'houseofsunny.co.uk', 'shopify', '15712855359871', 'VINTAGE ROSE TROUSER', 'Trousers', array['WOMENS','WOMENS ALL']::text[], 86.0, 34.4, 'GBP', 'https://houseofsunny.co.uk/products/womens-trousers-vintage-rose-floral-cotton-pants', 'https://cdn.shopify.com/s/files/1/0737/8616/3481/files/RoseBalloonPants.jpg?v=1792419359', array['https://cdn.shopify.com/s/files/1/0737/8616/3481/files/RoseBalloonPants.jpg?v=1792419359','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/ROSETROUSERS.jpg?v=1785425801','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/ROSETROUSERS_1.jpg?v=1792142850','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/Ecom_3.jpg?v=1788527382','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/Ecom_2.jpg?v=1788527381','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/ROSETROUSERS_a6ce2589-42b7-487b-b554-1aa3a0c17770.jpg?v=1785830853']::text[], 'Crafted from 100% cotton featuring a vintage-inspired floral rose and stripe print on an off-white base. Relaxed, wide-leg silhouette. Comfortable, elasticated paperbag-style waistband trimmed with delicate ruffles and an adjustable drawcord tie. Finished with functional drawstring ankle ties to convert the hem from a wide leg to a subtle cinch. Aris is 5''9 and wears a size S/8 Designed as part of a matching two-piece set. Pairs with our Vintage Rose Top or Mesh Top.', 'House of Sunny', array['UK 6','UK 8','UK 10','UK 12','UK 14','UK 16','UK 18']::text[], '2026-07-30T16:36:56+01:00', array['lil-miquela-4']::text[], true, '2026-11-25T19:00:48.895572+00:00'),
