('House of Sunny', 'houseofsunny.co.uk', 'shopify', '15712837501311', 'CHOCOLATE SECOND SKIN DRAPED  TOP', 'Tops', array['WOMENS','WOMENS ALL']::text[], 54.0, 32.4, 'GBP', 'https://houseofsunny.co.uk/products/womens-tops-chocolate-brown-draped-mesh-scarf-top', 'https://cdn.shopify.com/s/files/1/0737/8616/3481/files/Instagrampost-30.png?v=1793094050', array['https://cdn.shopify.com/s/files/1/0737/8616/3481/files/Instagrampost-30.png?v=1793094050','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/Instagrampost-31_60919a82-0d02-41d3-9d10-c368fa4575c2.png?v=1793095735','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/BROWN-DRAPED-TOP.jpg?v=1785836620','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/BROWNDRAPEDTOP-5.jpg?v=1785424108','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/BROWNDRAPEDTOP_2fa72d1d-e4a2-4531-8624-c822880ddfaf.jpg?v=1785769172','https://cdn.shopify.com/s/files/1/0737/8616/3481/files/BROWNDRAPEDTOP-1_afffebcc-2857-4811-90ab-763becdc0f93.jpg?v=1785769172']::text[], 'Lightweight, semi-sheer fine mesh fabric in a rich chocolate brown shade. Designed with a soft, elegant cowl neck and an integrated, trailing neck scarf. Sleeveless, form-fitting silhouette detailed with flattering horizontal ruching along the sides. Versatile design that transitions effortlessly from day to night, ideal for pairing with low-rise trousers or skirts. Finished with a small, metallic silver-tone House of Sunny logo plaque Aris is 5''9 and wears a size S/8', 'House of Sunny', array['UK 6','UK 8','UK 10','UK 12','UK 14','UK 16','UK 18']::text[], '2026-07-30T16:25:43+01:00', array['imma-5']::text[], true, '2026-11-25T19:00:48.895572+00:00'),
